// === lrgrammar.rs:3178-3187 — `___expected_tokens` fn ===
/** `___expected_tokens(state)`. */
internal fun expectedTokens(state: Short): List<String> {
    return TERMINAL.mapIndexedNotNull { index, terminal ->
        val nextState = action(state, index)
        if (nextState.toInt() == 0) {
            null
        } else {
            terminal
        }
    }
}

// === lrgrammar.rs:3203-3303 — `___StateMachine` struct + `ParserDefinition` impl ===
// The Rust struct holds `text: &'input str` plus a phantom marker; in
// Kotlin we drop the lifetime entirely and keep just the input text. The
// `impl ___state_machine::ParserDefinition for ___StateMachine` block is
// realised directly on the class — each method forwards to the free
// function that the Rust impl also delegates to.
internal class StateMachine(
    internal val text: String,
) : io.github.kotlinmania.lalrpop_kotlin.runtime.ParserDefinition<
    Int,
    io.github.kotlinmania.lalrpop_kotlin.tok.Error,
    io.github.kotlinmania.lalrpop_kotlin.tok.Tok,
    Int,
    LrSymbol,
    Top,
    Short,
    io.github.kotlinmania.lalrpop_kotlin.runtime.ShortAction,
    Short,
    Int,
> {
    override fun startLocation(): Int {
        return 0
    }

    override fun startState(): Short {
        return 0
    }

    override fun tokenToIndex(token: io.github.kotlinmania.lalrpop_kotlin.tok.Tok): Int? =
        tokenToInteger(token)

    override fun action(state: Short, tokenIndex: Int): io.github.kotlinmania.lalrpop_kotlin.runtime.ShortAction =
        io.github.kotlinmania.lalrpop_kotlin.runtime.ShortAction(
            io.github.kotlinmania.lalrpop_kotlin.parser.action(state, tokenIndex),
        )

    override fun errorAction(state: Short): io.github.kotlinmania.lalrpop_kotlin.runtime.ShortAction =
        io.github.kotlinmania.lalrpop_kotlin.runtime.ShortAction(
            io.github.kotlinmania.lalrpop_kotlin.parser.action(state, 58),
        )

    override fun eofAction(state: Short): io.github.kotlinmania.lalrpop_kotlin.runtime.ShortAction =
        io.github.kotlinmania.lalrpop_kotlin.runtime.ShortAction(EOF_ACTION[state.toInt()])

    override fun goto(state: Short, nt: Int): Short =
        io.github.kotlinmania.lalrpop_kotlin.parser.goto(state, nt)

    override fun tokenToSymbol(tokenIndex: Int, token: io.github.kotlinmania.lalrpop_kotlin.tok.Tok): LrSymbol =
        io.github.kotlinmania.lalrpop_kotlin.parser.tokenToSymbol(tokenIndex, token)

    override fun expectedTokens(state: Short): List<String> =
        io.github.kotlinmania.lalrpop_kotlin.parser.expectedTokens(state)

    override fun expectedTokensFromStates(states: List<Short>): List<String> =
        io.github.kotlinmania.lalrpop_kotlin.parser.expectedTokensFromStates(states)

    override fun usesErrorRecovery(): Boolean = false

    override fun errorRecoverySymbol(
        recovery: io.github.kotlinmania.lalrpop_kotlin.runtime.ErrorRecovery<
            Int,
            io.github.kotlinmania.lalrpop_kotlin.tok.Tok,
            io.github.kotlinmania.lalrpop_kotlin.tok.Error,
        >,
    ): LrSymbol = error("error recovery not enabled for this grammar")

    override fun reduce(
        reduceIndex: Short,
        startLocation: Int?,
        states: MutableList<Short>,
        symbols: MutableList<io.github.kotlinmania.lalrpop_kotlin.runtime.SymbolTriple<Int, LrSymbol>>,
    ): io.github.kotlinmania.lalrpop_kotlin.runtime.ParseResult<
        Top,
        Int,
        io.github.kotlinmania.lalrpop_kotlin.tok.Tok,
        io.github.kotlinmania.lalrpop_kotlin.tok.Error,
    >? {
        return io.github.kotlinmania.lalrpop_kotlin.parser.reduce(
            text,
            reduceIndex, startLocation, states, symbols,
        )
    }

    override fun simulateReduce(action: Short): io.github.kotlinmania.lalrpop_kotlin.runtime.SimulatedReduce<Int> =
        io.github.kotlinmania.lalrpop_kotlin.parser.simulateReduce(action)
}

// === lrgrammar.rs:3304-3374 — `___token_to_integer` ===
// Maps a token to its column in the ACTION/EOF_ACTION tables.
// Returns null when the token is not a recognised terminal (LALRPOP's
// `___token_to_integer` returns `None` for the same case).
internal fun tokenToInteger(
    token: io.github.kotlinmania.lalrpop_kotlin.tok.Tok,
): Int?
{
    @Suppress("REDUNDANT_ELSE_IN_WHEN")
    return when (
        token
    ) {
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Enum -> 0
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Extern -> 1
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Grammar -> 2
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Match -> 3
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Else -> 4
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.If -> 5
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Mut -> 6
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Pub -> 7
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.In -> 8
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Type -> 9
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Where -> 10
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.For -> 11
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Bang -> 12
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Use -> 13
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Dyn -> 14
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Escape -> 15
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Id -> 16
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.MacroId -> 17
        is io.github.kotlinmania.lalrpop_kotlin.tok.Tok.Lifetime -> 18
